namespace SGSForms.Api.Services;

public partial class ExportService : IExportService
{
	private readonly AppDbContext _db;

	private readonly CurrentUser _me;

	private static readonly Color Green = new Color(0, 108, 78);

	private static readonly Color Muted = new Color(100, 117, 139);

	private static readonly Color LightBg = new Color(240, 244, 248);

	private static readonly Color Border = new Color(203, 213, 225);

	private static readonly Color Gold = new Color(201, 168, 76);

	private static readonly Color CardBg = new Color(246, 251, 249);

	private static readonly Color Ink = new Color(31, 41, 55);

	internal const string LOGO = "";

	public ExportService(AppDbContext db, CurrentUser me)
	{
		_db = db;
		_me = me;
	}

	private static string T(TimeOnly? t)
	{
		return t?.ToString("HH:mm") ?? "-";
	}

	private static string V(string? s)
	{
		if (!string.IsNullOrWhiteSpace(s))
		{
			return s;
		}
		return "-";
	}

	private static string Dur(TimeOnly? from, TimeOnly? to)
	{
		return CoordinationService.Elapsed(from, to) is int mins ? $"{mins / 60:00}:{mins % 60:00}" : "";
	}

	private static string N(int n)
	{
		return n.ToString();
	}

	public async Task<(byte[], string)> ReportPdfAsync(string kind, int id)
	{
		ReportKind reportKind = Parse.Kind(kind);
		if (!_me.HasAny(Permissions.ReportReaders))
		{
			throw AppException.Forbidden();
		}
		if (reportKind == ReportKind.Arrival)
		{
			ArrivalReport r = (await _db.ArrivalReports.AsNoTracking().Include((ArrivalReport x) => x.Station).Include((ArrivalReport x) => x.Services).Include((ArrivalReport x) => x.Delays)
				.FirstOrDefaultAsync((ArrivalReport x) => x.Id == id)) ?? throw AppException.NotFound("Report not found");
			if (!_me.CanAccessStation(r.StationId))
			{
				throw AppException.Forbidden();
			}
			Approval? appr = await ApprovalOf(ReportKind.Arrival, id);
			List<(string, List<(string, string)>)> sections = new List<(string, List<(string, string)>)>
			{
				("General Information", new List<(string, string)>
				{
					("Flight No", V(r.FlightNo)),
					("Route", V(r.Route)),
					("Aircraft Reg", V(r.AircraftReg)),
					("Date", r.FlightDate.ToString("yyyy-MM-dd")),
					("STA", T(r.Sta)),
					("ATA", T(r.Ata)),
					("Station", r.Station.Code),
					("Supervisor", V(r.SupervisorName))
				}),
				("Arrival Data", new List<(string, string)>
				{
					("Gate No", V(r.GateNo)),
					("Total Arriving Pax", N(r.TtlPaxArr)),
					("Total Wheelchairs", N(r.TtlWchr)),
					("Total Baggage", N(r.BagTotal)),
					("Additional Services", r.Services.Any() ? string.Join(", ", r.Services.Select((SGSForms.Api.Entities.ArrivalService s) => $"{s.Name} ({s.Count})")) : "-")
				}),
				("Operational Info", new List<(string, string)> { ("Remarks", V(r.Remarks)) })
			};
			List<string[]> delays = r.Delays.Select((ArrivalDelay d) => new string[3]
			{
				V(d.Code),
				V(d.Reason),
				N(d.DurationMinutes)
			}).ToList();
			string reference = $"SGS-ARR-{r.Id}-{r.FlightDate:yyyyMMdd}";
			byte[] item = BuildPdf(r.FlightNo, "Arrival Report", StatusLabel(r.Status), sections, delays, appr, reference, showDelays: false);
			return (item, $"Arrival_{Safe(r.FlightNo)}_{r.FlightDate:yyyyMMdd}.pdf");
		}
		DepartureReport r2 = (await _db.DepartureReports.AsNoTracking().Include((DepartureReport x) => x.Station).Include((DepartureReport x) => x.Delays).Include((DepartureReport x) => x.StaffProductivity)
			.FirstOrDefaultAsync((DepartureReport x) => x.Id == id)) ?? throw AppException.NotFound("Report not found");
		if (!_me.CanAccessStation(r2.StationId))
		{
			throw AppException.Forbidden();
		}
		Approval? appr2 = await ApprovalOf(ReportKind.Departure, id);
		List<(string, List<(string, string)>)> list = new List<(string, List<(string, string)>)>
		{
			("General Information", new List<(string, string)>
			{
				("Flight No", V(r2.FlightNo)),
				("Route (Destination)", V(r2.Route)),
				("Aircraft Reg", V(r2.AircraftReg)),
				("Date", r2.FlightDate.ToString("yyyy-MM-dd")),
				("STD", T(r2.Std)),
				("ATD", T(r2.Atd)),
				("Station (Originating)", r2.Station.Code),
				("Counter No", V(r2.CounterNo)),
				("Counters Started", T(r2.CountersStartedAt)),
				("Supervisor", V(r2.SupervisorName))
			}),
			("Passengers", new List<(string, string)>
			{
				("F Pax", N(r2.PaxF)),
				("J Pax", N(r2.PaxJ)),
				("W Pax", N(r2.PaxW)),
				("Y Pax", N(r2.PaxY)),
				("INF", N(r2.PaxInf)),
				("Hajj/Umrah", N(r2.PaxHajj)),
				("Altanfeethi", N(r2.PaxExec)),
				("VIP", N(r2.PaxVip)),
				("No Show", N(r2.NoShow)),
				("Offloaded", N(r2.Offloaded)),
				("Total Passengers", N(r2.PaxTotal))
			}),
			("Baggage", new List<(string, string)>
			{
				("Checked-in Bags", N(r2.BagNormal)),
				("Wheelchair", N(r2.BagWchr)),
				("CBBG", N(r2.BagCbbg)),
				("STCR", N(r2.BagStcr)),
				("AVIH/PETC", N(r2.BagAvih)),
				("VIP/CIP", N(r2.BagVip)),
				("Zamzam", N(r2.BagZamzam)),
				("Hajj Baggage", N(r2.BagHajj)),
				("Total Baggage", N(r2.BagTotal)),
				("Excess Tickets", N(r2.ExcessTickets)),
				("Excess Sales", r2.ExcessSales.ToString("0.00"))
			}),
			("Boarding", new List<(string, string)>
			{
				("Gate", V(r2.BoardingGate)),
				("Bus/Jetway", r2.BoardingMode?.ToString() ?? "-"),
				("Boarding Started", T(r2.BoardingStarted)),
				("Boarding Completed", T(r2.BoardingCompleted)),
				("Total Buses", N(r2.TotalBuses)),
				("Special Handling", V(r2.SpecialHandling))
			}),
			("Operational Info", new List<(string, string)> { ("Remarks", V(r2.Remarks)) })
		};
		if (r2.StaffProductivity.Any())
		{
			list.Add(("Staff Productivity", r2.StaffProductivity.Select((StaffProductivity s) => (V(s.StaffName), $"{s.PassengersServed} pax - {V(s.Comments)}")).ToList()));
		}
		List<string[]> delays2 = r2.Delays.Select((DepartureDelay d) => new string[3]
		{
			V(d.Code),
			V(d.Reason),
			N(d.DurationMinutes)
		}).ToList();
		string reference2 = $"SGS-DEP-{r2.Id}-{r2.FlightDate:yyyyMMdd}";
		byte[] item2 = BuildPdf(r2.FlightNo, "Departure Report", StatusLabel(r2.Status), list, delays2, appr2, reference2);
		return (item2, $"Departure_{Safe(r2.FlightNo)}_{r2.FlightDate:yyyyMMdd}.pdf");
	}

	private async Task<Approval?> ApprovalOf(ReportKind k, int reportId)
	{
		return await (from a in _db.Approvals.AsNoTracking()
			where (int)a.ReportKind == (int)k && (int)a.Decision == 0 && (((int)k == 0) ? (a.ArrivalReportId == (int?)reportId) : (a.DepartureReportId == (int?)reportId))
			orderby a.ApprovedAt descending
			select a).FirstOrDefaultAsync();
	}

	private byte[] BuildPdf(string flightNo, string kindLabel, string statusLabel, List<(string Title, List<(string, string)> Fields)> sections, List<string[]> delays, Approval? appr, string reference, bool showDelays = true, List<string[]>? activities = null)
	{
		Document document = new Document();
		Style normal = document.Styles["Normal"]!;
		normal.Font.Name = "Arial";
		normal.Font.Size = 8;
		normal.ParagraphFormat.SpaceAfter = 0;
		Section section = document.AddSection();
		section.PageSetup.PageFormat = PageFormat.A4;
		section.PageSetup.TopMargin = Unit.FromCentimeter(0.9);
		section.PageSetup.BottomMargin = Unit.FromCentimeter(0.9);
		section.PageSetup.LeftMargin = Unit.FromCentimeter(1.1);
		section.PageSetup.RightMargin = Unit.FromCentimeter(1.1);
		Table table = section.AddTable();
		table.AddColumn(Unit.FromCentimeter(9.4));
		table.AddColumn(Unit.FromCentimeter(9.4));
		Row row = table.AddRow();
		row.Cells[0].VerticalAlignment = VerticalAlignment.Center;
		row.Cells[1].VerticalAlignment = VerticalAlignment.Center;
		try
		{
			Paragraph paragraph = row.Cells[0].AddParagraph();
			Image image = paragraph.AddImage("base64:" + LOGO);
			image.LockAspectRatio = true;
			image.Width = Unit.FromCentimeter(4.0);
		}
		catch
		{
			Paragraph paragraph2 = row.Cells[0].AddParagraph("Saudi Ground Services");
			paragraph2.Format.Font.Bold = true;
			paragraph2.Format.Font.Size = 12;
			paragraph2.Format.Font.Color = Green;
		}
		Cell cell = row.Cells[1];
		Paragraph paragraph3 = cell.AddParagraph("FLIGHT HANDLING REPORT");
		paragraph3.Format.Alignment = ParagraphAlignment.Right;
		paragraph3.Format.Font.Bold = true;
		paragraph3.Format.Font.Size = 12;
		paragraph3.Format.Font.Color = Green;
		string[] array = new string[3]
		{
			kindLabel,
			"Status: " + statusLabel,
			"Flight: " + flightNo
		};
		string[] array2 = array;
		foreach (string text in array2)
		{
			Paragraph paragraph4 = cell.AddParagraph(text);
			paragraph4.Format.Alignment = ParagraphAlignment.Right;
			paragraph4.Format.Font.Size = 8;
			paragraph4.Format.Font.Color = Muted;
			if (text == kindLabel)
			{
				paragraph4.Format.Font.Bold = true;
				paragraph4.Format.Font.Color = Ink;
				paragraph4.Format.SpaceBefore = "2pt";
			}
		}
		Table table2 = section.AddTable();
		table2.AddColumn(Unit.FromCentimeter(18.8));
		Row row2 = table2.AddRow();
		row2.Height = Unit.FromCentimeter(0.1);
		row2.HeightRule = RowHeightRule.Exactly;
		row2.Shading.Color = Green;
		row2.Cells[0].AddParagraph();
		section.AddParagraph().Format.SpaceAfter = Unit.FromCentimeter(0.05);
		foreach (var section2 in sections)
		{
			AddFieldsSection(section, section2.Title, section2.Fields);
		}
		if (activities != null)
		{
			AddActivities(section, activities);
		}
		if (showDelays)
		{
			AddDelays(section, delays);
		}
		if (appr != null)
		{
			AddApproval(section, appr);
		}
		Paragraph paragraph5 = section.AddParagraph($"Document Ref: {reference}    •    Generated: {DateTime.Now:yyyy-MM-dd HH:mm}");
		paragraph5.Format.SpaceBefore = Unit.FromCentimeter(0.2);
		paragraph5.Format.Font.Size = 7;
		paragraph5.Format.Font.Color = Muted;
		paragraph5.Format.Alignment = ParagraphAlignment.Center;
		PdfDocumentRenderer pdfDocumentRenderer = new PdfDocumentRenderer
		{
			Document = document
		};
		pdfDocumentRenderer.RenderDocument();
		using MemoryStream memoryStream = new MemoryStream();
		pdfDocumentRenderer.PdfDocument.Save(memoryStream);
		return memoryStream.ToArray();
	}

	private static void SectionHeading(Section sec, string title)
	{
		Paragraph paragraph = sec.AddParagraph(title);
		paragraph.Format.Font.Bold = true;
		paragraph.Format.Font.Size = 9.5;
		paragraph.Format.Font.Color = Green;
		paragraph.Format.SpaceBefore = Unit.FromCentimeter(0.12);
		paragraph.Format.SpaceAfter = Unit.FromCentimeter(0.04);
	}

	private static void AddFieldsSection(Section sec, string title, List<(string, string)> fields)
	{
		SectionHeading(sec, title);
		Table table = sec.AddTable();
		table.Borders.Width = 0.5;
		table.Borders.Color = Border;
		table.AddColumn(Unit.FromCentimeter(3.6));
		table.AddColumn(Unit.FromCentimeter(5.8));
		table.AddColumn(Unit.FromCentimeter(3.6));
		table.AddColumn(Unit.FromCentimeter(5.8));
		for (int i = 0; i < fields.Count; i += 2)
		{
			Row row = table.AddRow();
			Cell(row.Cells[0], fields[i].Item1, label: true);
			Cell(row.Cells[1], fields[i].Item2, label: false);
			if (i + 1 < fields.Count)
			{
				Cell(row.Cells[2], fields[i + 1].Item1, label: true);
				Cell(row.Cells[3], fields[i + 1].Item2, label: false);
			}
			else
			{
				row.Cells[2].AddParagraph("");
				row.Cells[3].AddParagraph("");
			}
		}
	}

	private static void Cell(Cell c, string text, bool label)
	{
		c.VerticalAlignment = VerticalAlignment.Center;
		Paragraph paragraph = c.AddParagraph(text);
		paragraph.Format.Font.Size = 7.5;
		paragraph.Format.SpaceBefore = "0.4pt";
		paragraph.Format.SpaceAfter = "0.4pt";
		if (label)
		{
			c.Shading.Color = LightBg;
			paragraph.Format.Font.Color = Muted;
		}
		else
		{
			paragraph.Format.Font.Bold = true;
		}
	}

	private static void AddDelays(Section sec, List<string[]> delays)
	{
		SectionHeading(sec, "Delays");
		if (delays.Count == 0)
		{
			Paragraph paragraph = sec.AddParagraph("None");
			paragraph.Format.Font.Color = Muted;
			return;
		}
		Table table = sec.AddTable();
		table.Borders.Width = 0.5;
		table.Borders.Color = Border;
		table.AddColumn(Unit.FromCentimeter(3.0));
		table.AddColumn(Unit.FromCentimeter(10.0));
		table.AddColumn(Unit.FromCentimeter(4.0));
		Row row = table.AddRow();
		row.Shading.Color = LightBg;
		string[] array = new string[3] { "Code", "Reason", "Duration (min)" };
		for (int i = 0; i < 3; i++)
		{
			Paragraph paragraph2 = row.Cells[i].AddParagraph(array[i]);
			paragraph2.Format.Font.Bold = true;
			paragraph2.Format.Font.Color = Muted;
		}
		foreach (string[] delay in delays)
		{
			Row row2 = table.AddRow();
			for (int j = 0; j < 3; j++)
			{
				row2.Cells[j].AddParagraph(delay[j]);
			}
		}
	}

	private static void AddActivities(Section sec, List<string[]> rows)
	{
		SectionHeading(sec, "Activities Time Chart");
		Table table = sec.AddTable();
		table.Borders.Width = 0.5;
		table.Borders.Color = Border;
		double[] widths = new double[5] { 6.0, 2.6, 2.6, 2.6, 5.0 };
		double[] array = widths;
		foreach (double w in array)
		{
			table.AddColumn(Unit.FromCentimeter(w));
		}
		Row head = table.AddRow();
		head.Shading.Color = LightBg;
		string[] headers = new string[5] { "Activity", "Actual Start", "Actual Finish", "Duration", "Remarks" };
		for (int j = 0; j < headers.Length; j++)
		{
			Paragraph hp = head.Cells[j].AddParagraph(headers[j]);
			hp.Format.Font.Bold = true;
			hp.Format.Font.Size = 7.5;
			hp.Format.Font.Color = Muted;
			if (j > 0 && j < 4)
			{
				hp.Format.Alignment = ParagraphAlignment.Center;
			}
		}
		foreach (string[] r in rows)
		{
			Row tr = table.AddRow();
			for (int k = 0; k < headers.Length; k++)
			{
				Paragraph cp = tr.Cells[k].AddParagraph(r[k]);
				cp.Format.Font.Size = 7.5;
				if (k > 0 && k < 4)
				{
					cp.Format.Alignment = ParagraphAlignment.Center;
				}
			}
		}
	}

	public async Task<(byte[], string)> CoordinationPdfAsync(int id)
	{
		if (!_me.HasAny(Permissions.CoordinationView, Permissions.CoordinationCreate))
		{
			throw AppException.Forbidden();
		}
		CoordinationSheet r = (await _db.CoordinationSheets.AsNoTracking().Include((CoordinationSheet x) => x.Station).Include((CoordinationSheet x) => x.Activities).Include((CoordinationSheet x) => x.Buses)
			.FirstOrDefaultAsync((CoordinationSheet x) => x.Id == id)) ?? throw AppException.NotFound("Sheet not found");
		if (!_me.CanAccessStation(r.StationId))
		{
			throw AppException.Forbidden();
		}
		string handling = (r.Turnaround ? "Turnaround" : (r.Transit ? "Transit" : (r.Terminating ? "Terminating" : (r.Originating ? "Originating" : "-"))));
		string dly = ((r.DlyAmount > 0) ? $"{r.DlyAmount / 60:00}:{r.DlyAmount % 60:00}" : "-");
		string flight = ((!string.IsNullOrWhiteSpace(r.ArrFlightNo)) ? r.ArrFlightNo : V(r.DepFlightNo));
		List<(string, List<(string, string)>)> sections = new List<(string, List<(string, string)>)>
		{
			("General Information", new List<(string, string)>
			{
				("Date", r.FlightDate.ToString("yyyy-MM-dd")),
				("AC Type", V(r.AcType)),
				("AC Reg", V(r.AcReg)),
				("Handling Type", handling),
				("Station", r.Station.Code),
				("Supervisor", V(r.SupervisorName))
			}),
			("Arrival", new List<(string, string)>
			{
				("Flight No", V(r.ArrFlightNo)),
				("From", V(r.ArrFrom)),
				("Pax (F)", N(r.ArrPaxF)),
				("Pax (J)", N(r.ArrPaxJ)),
				("Pax (Y)", N(r.ArrPaxY)),
				("Total Pax", N(r.ArrPaxF + r.ArrPaxJ + r.ArrPaxY)),
				("STA", T(r.Sta)),
				("ATA", T(r.Ata)),
				("Arrival Buses", Buses("arrival"))
			}),
			("Departure", new List<(string, string)>
			{
				("Flight No", V(r.DepFlightNo)),
				("To", V(r.DepTo)),
				("Pax (F)", N(r.DepPaxF)),
				("Pax (J)", N(r.DepPaxJ)),
				("Pax (Y)", N(r.DepPaxY)),
				("Total Pax", N(r.DepPaxF + r.DepPaxJ + r.DepPaxY)),
				("STD", T(r.Std)),
				("ATD", T(r.Atd)),
				("Departure Buses", Buses("departure"))
			}),
			("Delay", new List<(string, string)>
			{
				("DLY Amount", dly),
				("Delay Code", V(r.DelayCode)),
				("Remarks", V(r.Remarks))
			})
		};
		if (!r.Terminating)
		{
			sections.Insert(sections.Count - 1, ("Times", new List<(string, string)> { ("GAIN Time", V(r.GainTime)) }));
		}
		Dictionary<string, CoordinationActivity> byKey = r.Activities.GroupBy(a => a.ActivityKey).ToDictionary(g => g.Key, g => g.First());
		List<string[]> acts = CoordinationActivities.All.Select(delegate((string Key, string Label) def)
		{
			byKey.TryGetValue(def.Key, out var value);
			return new string[5]
			{
				def.Label,
				(value == null) ? "" : T(value.ActualStart),
				(value == null) ? "" : T(value.ActualFinish),
				(value == null) ? "" : Dur(value.ActualStart, value.ActualFinish),
				value?.Remarks ?? ""
			};
		}).ToList();
		string status = ((r.Status == ReportStatus.Draft) ? "Draft" : "Completed");
		string reference = $"SGS-COORD-{r.Id}-{r.FlightDate:yyyyMMdd}";
		byte[] bytes = BuildPdf(flight, "Coordination Sheet", status, sections, new List<string[]>(), null, reference, showDelays: false, acts);
		return (bytes, $"Coordination_{Safe(flight)}_{r.FlightDate:yyyyMMdd}.pdf");
		string Buses(string phase)
		{
			List<CoordinationBus> list = r.Buses.Where((CoordinationBus b) => b.Phase == phase).ToList();
			if (list.Count != 0)
			{
				return string.Join(", ", list.Select((CoordinationBus b) => V(b.BusNo) + " (" + T(b.Time) + ")"));
			}
			return "-";
		}
	}

	private static void AddApproval(Section sec, Approval a)
	{
		sec.AddParagraph().Format.SpaceBefore = Unit.FromCentimeter(0.12);
		Table table = sec.AddTable();
		table.AddColumn(Unit.FromCentimeter(12.8));
		table.AddColumn(Unit.FromCentimeter(6.0));
		Row row = table.AddRow();
		row.Shading.Color = Green;
		row.VerticalAlignment = VerticalAlignment.Center;
		row.TopPadding = "2pt";
		row.BottomPadding = "2pt";
		Paragraph paragraph = row.Cells[0].AddParagraph("Airline Approval & Signature");
		paragraph.Format.Font.Color = Colors.White;
		paragraph.Format.Font.Bold = true;
		paragraph.Format.Font.Size = 10.5;
		Paragraph paragraph2 = row.Cells[1].AddParagraph($"Approved  •  {a.ApprovedAt:yyyy-MM-dd HH:mm}");
		paragraph2.Format.Alignment = ParagraphAlignment.Right;
		paragraph2.Format.Font.Color = new Color(232, 245, 240);
		paragraph2.Format.Font.Size = 8;
		Table table2 = sec.AddTable();
		table2.Borders.Width = 0.5;
		table2.Borders.Color = Border;
		table2.AddColumn(Unit.FromCentimeter(9.4));
		table2.AddColumn(Unit.FromCentimeter(9.4));
		int num = Math.Clamp(a.Satisfaction, 0, 5);
		Row row2 = table2.AddRow();
		row2.Cells[0].MergeRight = 1;
		row2.Shading.Color = CardBg;
		row2.TopPadding = "2pt";
		row2.BottomPadding = "2pt";
		Paragraph paragraph3 = row2.Cells[0].AddParagraph("SATISFACTION RATING");
		paragraph3.Format.Font.Size = 7.5;
		paragraph3.Format.Font.Color = Muted;
		paragraph3.Format.Font.Bold = true;
		Paragraph paragraph4 = row2.Cells[0].AddParagraph();
		paragraph4.Format.SpaceBefore = "1pt";
		FormattedText formattedText = paragraph4.AddFormattedText(string.Concat(Enumerable.Repeat("● ", num)));
		formattedText.Color = Gold;
		formattedText.Size = 12;
		if (num < 5)
		{
			FormattedText formattedText2 = paragraph4.AddFormattedText(string.Concat(Enumerable.Repeat("○ ", 5 - num)));
			formattedText2.Color = Border;
			formattedText2.Size = 12;
		}
		FormattedText formattedText3 = paragraph4.AddFormattedText($"    {a.Satisfaction} / 5");
		formattedText3.Color = Green;
		formattedText3.Bold = true;
		formattedText3.Size = 10;
		if (!string.IsNullOrWhiteSpace(a.AirlineRemarks))
		{
			Row row3 = table2.AddRow();
			row3.Cells[0].MergeRight = 1;
