	private static string? NormalizeBase64(string? dataUrl)
	{
		if (string.IsNullOrWhiteSpace(dataUrl))
		{
			return null;
		}
		int num = dataUrl.IndexOf("base64,", StringComparison.OrdinalIgnoreCase);
		string text;
		if (num < 0)
		{
			text = dataUrl;
		}
		else
		{
			int num2 = num + 7;
			text = dataUrl.Substring(num2, dataUrl.Length - num2);
		}
		string text3 = text;
		try
		{
			Convert.FromBase64String(text3);
			return text3;
		}
		catch
		{
			return null;
		}
	}

	private static string StatusLabel(ReportStatus s)
	{
		return s switch
		{
			ReportStatus.Draft => "Draft", 
			ReportStatus.Submitted => "Pending Approval", 
			ReportStatus.Approved => "Approved", 
			ReportStatus.Returned => "Returned", 
			_ => s.ToString(), 
		};
	}

	/// <summary>Letters and digits only, so the value is safe inside a download file name.</summary>
	private static string Safe(string? s)
	{
		return new string((s ?? "").Where(char.IsLetterOrDigit).ToArray());
	}

	private static string DT(DateTime? t)
	{
		return t?.ToString("yyyy-MM-dd HH:mm") ?? "-";
	}

	private static string J(string sep, IEnumerable<string> xs)
	{
		List<string> list = xs.ToList();
		if (list.Count != 0)
		{
			return string.Join(sep, list);
		}
		return "-";
	}

	/// <summary>What the export dialog selected; every list endpoint filter is applied the same way.</summary>
	private sealed record ExcelFilter(List<ReportStatus> Statuses, bool Arrivals, bool Departures, DateOnly? From, DateOnly? To, int? Scope, string? Airline, string? Term);

	/// <summary>
	/// Statuses: comma separated (draft, submitted, approved, returned) or "all" for every status the user may list.
	/// Each requested status needs the permission of the page that lists it.
	/// </summary>
	private ExcelFilter ReadFilter(string? status, string? kind, string? from, string? to, int? stationId, string? airline, string? q)
	{
		List<ReportStatus> statuses;
		if (string.Equals(status?.Trim(), "all", StringComparison.OrdinalIgnoreCase))
		{
			statuses = Enum.GetValues<ReportStatus>().Where(st => _me.Has(Permissions.ListPermissionFor(st))).ToList();
			if (statuses.Count == 0)
			{
				throw AppException.Forbidden();
			}
		}
		else
		{
			statuses = (status ?? "").Split(',', StringSplitOptions.RemoveEmptyEntries | StringSplitOptions.TrimEntries)
				.Select(x => Parse.OptionalStatus(x) ?? throw new AppException("حالة غير صالحة: " + x))
				.Distinct().ToList();
			if (statuses.Count == 0)
			{
				statuses.Add(ReportStatus.Submitted);
			}
			if (statuses.Any(st => !_me.Has(Permissions.ListPermissionFor(st))))
			{
				throw AppException.Forbidden();
			}
		}
		string k = (kind ?? "all").Trim().ToLowerInvariant();
		if (k != "all" && k != "arrival" && k != "departure")
		{
			throw new AppException("نوع التقرير غير صالح");
		}
		(DateOnly? fromDay, DateOnly? toDay) = Parse.Range(from, to);
		return new ExcelFilter(statuses, k != "departure", k != "arrival", fromDay, toDay,
			_me.StationScope(stationId), FlightNo.Filter(airline), Parse.Search(q));
	}

	private IQueryable<ArrivalReport> Arrivals(ExcelFilter f)
	{
		return _db.ArrivalReports.AsNoTracking()
			.Where(x => f.Statuses.Contains(x.Status) && (f.Scope == null || x.StationId == f.Scope)
				&& (f.From == null || x.FlightDate >= f.From) && (f.To == null || x.FlightDate <= f.To)
				&& (f.Term == null || x.FlightNo.Contains(f.Term) || x.Route.Contains(f.Term) || x.Station.Code.Contains(f.Term)));
	}

	private IQueryable<DepartureReport> Departures(ExcelFilter f)
	{
		return _db.DepartureReports.AsNoTracking()
			.Where(x => f.Statuses.Contains(x.Status) && (f.Scope == null || x.StationId == f.Scope)
				&& (f.From == null || x.FlightDate >= f.From) && (f.To == null || x.FlightDate <= f.To)
				&& (f.Term == null || x.FlightNo.Contains(f.Term) || x.Route.Contains(f.Term) || x.Station.Code.Contains(f.Term)));
	}

	/// <summary>Airline is matched on the exact flight-number prefix, so it is applied after loading.</summary>
	private static bool AirlineMatches(ExcelFilter f, string flightNo) => f.Airline == null || FlightNo.Prefix(flightNo) == f.Airline;

	public async Task<(int Arrivals, int Departures)> ExcelCountAsync(string? status, string? kind, string? from, string? to, int? stationId, string? airline, string? q)
	{
		ExcelFilter f = ReadFilter(status, kind, from, to, stationId, airline, q);
		List<string> arr = f.Arrivals ? await Arrivals(f).Select(x => x.FlightNo).ToListAsync() : new List<string>();
		List<string> dep = f.Departures ? await Departures(f).Select(x => x.FlightNo).ToListAsync() : new List<string>();
		return (arr.Count(n => AirlineMatches(f, n)), dep.Count(n => AirlineMatches(f, n)));
	}

	/// <summary>Largest export in one file; the dialog shows the count first so the user can narrow the selection.</summary>
	public const int MaxExcelRows = 20_000;

	private static void EnsureExportSize(int rows)
	{
		if (rows > MaxExcelRows)
		{
			throw new AppException($"التصدير يتجاوز {MaxExcelRows:N0} سجل ({rows:N0}) — ضيّق الفترة أو الفلاتر");
		}
	}

	public async Task<(byte[], string)> ListExcelAsync(string? status, string? kind, string? from, string? to, int? stationId, string? airline, string? q)
	{
		ExcelFilter f = ReadFilter(status, kind, from, to, stationId, airline, q);
		EnsureExportSize((f.Arrivals ? await Arrivals(f).CountAsync() : 0) + (f.Departures ? await Departures(f).CountAsync() : 0));
		List<ArrivalReport> arrList = f.Arrivals
			? (await Arrivals(f).Include(x => x.Station).Include(x => x.Services).Include(x => x.Delays)
				.OrderByDescending(x => x.FlightDate).ToListAsync()).Where(x => AirlineMatches(f, x.FlightNo)).ToList()
			: new List<ArrivalReport>();
		List<DepartureReport> source = f.Departures
			? (await Departures(f).Include(x => x.Station).Include(x => x.Delays).Include(x => x.StaffProductivity)
				.OrderByDescending(x => x.FlightDate).ToListAsync()).Where(x => AirlineMatches(f, x.FlightNo)).ToList()
			: new List<DepartureReport>();
		string? stationCode = f.Scope.HasValue ? await _db.Stations.Where(s => s.Id == f.Scope.Value).Select(s => s.Code).FirstOrDefaultAsync() : null;
		string period = (f.From.HasValue || f.To.HasValue) ? ("   ·   " + (f.From?.ToString("yyyy-MM-dd") ?? "…") + " → " + (f.To?.ToString("yyyy-MM-dd") ?? "…")) : "";
		string text3 = string.Join(" + ", f.Statuses.Select(StatusLabel)) + period
			+ (stationCode != null ? "   ·   Station: " + stationCode : "")
			+ (f.Airline != null ? "   ·   Airline: " + f.Airline : "")
