				V(r.AircraftReg),
				T(r.Sta),
				T(r.Ata),
				V(r.SupervisorName),
				DT(r.ReportTime),
				V(r.GateNo),
				r.TtlPaxArr,
				r.TtlWchr,
				r.BagTotal,
				J(", ", r.Services.Select((SGSForms.Api.Entities.ArrivalService s) => $"{s.Name} ({s.Count})")),
				V(r.Remarks),
				StatusLabel(r.Status)
