			BuildSheet(ws, "SGS Flight Handling — Arrivals — " + text3, groups, heads, rows, new int[3] { 11, 12, 13 }, Array.Empty<int>());
		}
		if (f.Departures)
		{
			IXLWorksheet ws2 = xLWorkbook.Worksheets.Add("Departures");
			(string, int)[] groups2 = new(string, int)[6]
			{
				("General Information", 11),
				("Passengers", 11),
				("Baggage", 11),
				("Boarding", 6),
				("Additional", 3),
				("", 1)
			};
			string[] heads2 = new string[43]
			{
				"Flight No", "Date", "Station (Originating)", "Route (Destination)", "Aircraft Reg", "STD", "ATD", "Counter No", "Counters Started", "Supervisor",
				"Report Time", "F", "J", "W", "Y", "INF", "Hajj/Umrah", "Altanfeethi", "VIP", "No Show",
				"Offloaded", "Total Passengers", "Checked-in Bags", "Wheelchair", "CBBG", "STCR", "AVIH/PETC", "VIP/CIP", "Zamzam", "Hajj Baggage",
				"Total Baggage", "Excess Tickets", "Excess Sales", "Gate", "Bus/Jetway", "Boarding Started", "Boarding Completed", "Total Buses", "Special Handling", "Delays",
				"Staff Productivity", "Remarks", "Status"
			};
			List<object[]> rows2 = source.Select((DepartureReport r) => new object[43]
			{
				r.FlightNo,
				r.FlightDate.ToString("yyyy-MM-dd"),
				r.Station.Code,
				V(r.Route),
				V(r.AircraftReg),
				T(r.Std),
