		string range = f.From.HasValue || f.To.HasValue ? $"_{f.From:yyyyMMdd}-{f.To:yyyyMMdd}" : "";
		return (memoryStream.ToArray(), $"{what}{(f.Airline != null ? "_" + Safe(f.Airline) : "")}{range}_{DateTime.Now:yyyyMMdd}.xlsx");
	}

	private static void BuildSheet(IXLWorksheet ws, string title, (string Name, int Span)[] groups, string[] heads, List<object[]> rows, int[] intCols, int[] decCols)
	{
		int num = heads.Length;
		XLColor xLColor = XLColor.FromHtml("#006C4E");
		XLColor xLColor2 = XLColor.FromHtml("#E8F5F0");
		XLColor xLColor3 = XLColor.FromHtml("#F5F9F7");
		XLColor xLColor4 = XLColor.FromHtml("#CBD5E1");
		IXLCell iXLCell = ws.Range(1, 1, 1, num).Merge().FirstCell();
		iXLCell.Value = title;
		iXLCell.Style.Font.Bold = true;
		iXLCell.Style.Font.FontSize = 13.0;
		iXLCell.Style.Font.FontColor = xLColor;
		iXLCell.Style.Alignment.Vertical = XLAlignmentVerticalValues.Center;
		ws.Row(1).Height = 24.0;
		int num2 = 1;
		bool flag = false;
		for (int i = 0; i < groups.Length; i++)
		{
			(string, int) tuple = groups[i];
			if (!string.IsNullOrEmpty(tuple.Item1))
			{
				IXLCell iXLCell2 = ws.Range(2, num2, 2, num2 + tuple.Item2 - 1).Merge().FirstCell();
				iXLCell2.Value = tuple.Item1;
				iXLCell2.Style.Font.Bold = true;
				iXLCell2.Style.Font.FontSize = 10.0;
				iXLCell2.Style.Font.FontColor = xLColor;
				iXLCell2.Style.Fill.BackgroundColor = (flag ? xLColor3 : xLColor2);
				iXLCell2.Style.Alignment.Horizontal = XLAlignmentHorizontalValues.Center;
				iXLCell2.Style.Alignment.Vertical = XLAlignmentVerticalValues.Center;
			}
			num2 += tuple.Item2;
			flag = !flag;
		}
		ws.Row(2).Height = 18.0;
		for (int j = 0; j < num; j++)
		{
			IXLCell iXLCell3 = ws.Cell(3, j + 1);
			iXLCell3.Value = heads[j];
			iXLCell3.Style.Font.Bold = true;
			iXLCell3.Style.Fill.BackgroundColor = xLColor;
			iXLCell3.Style.Font.FontColor = XLColor.White;
			iXLCell3.Style.Alignment.Vertical = XLAlignmentVerticalValues.Center;
		}
		ws.Row(3).Height = 20.0;
		for (int k = 0; k < rows.Count; k++)
		{
			for (int l = 0; l < num; l++)
			{
				ws.Cell(4 + k, l + 1).Value = XLCellValue.FromObject(rows[k][l]);
			}
			if (k % 2 == 1)
			{
				ws.Range(4 + k, 1, 4 + k, num).Style.Fill.BackgroundColor = xLColor3;
			}
		}
		int val = ((rows.Count == 0) ? 4 : (4 + rows.Count - 1));
		if (rows.Count == 0)
		{
			IXLCell iXLCell4 = ws.Range(4, 1, 4, num).Merge().FirstCell();
			iXLCell4.Value = "No reports";
			iXLCell4.Style.Font.Italic = true;
			iXLCell4.Style.Font.FontColor = XLColor.Gray;
			iXLCell4.Style.Alignment.Horizontal = XLAlignmentHorizontalValues.Center;
		}
		foreach (int column in intCols)
		{
			ws.Column(column).Style.NumberFormat.Format = "#,##0";
		}
		foreach (int column2 in decCols)
		{
			ws.Column(column2).Style.NumberFormat.Format = "#,##0.00";
		}
		IXLRange iXLRange = ws.Range(3, 1, Math.Max(val, 4), num);
		iXLRange.Style.Border.OutsideBorder = XLBorderStyleValues.Thin;
		iXLRange.Style.Border.InsideBorder = XLBorderStyleValues.Thin;
		iXLRange.Style.Border.OutsideBorderColor = xLColor4;
		iXLRange.Style.Border.InsideBorderColor = xLColor4;
		ws.Range(3, 1, Math.Max(val, 4), num).SetAutoFilter();
		ws.SheetView.FreezeRows(3);
		ws.SheetView.FreezeColumns(1);
		for (int num3 = 1; num3 <= num; num3++)
		{
			ws.Column(num3).AdjustToContents();
			if (ws.Column(num3).Width > 45.0)
			{
				ws.Column(num3).Width = 45.0;
			}
			if (ws.Column(num3).Width < 9.0)
			{
				ws.Column(num3).Width = 9.0;
			}
		}
	}
